from machine import Pin, ADC, PWM
from time import sleep
rouge = Pin(5, Pin.OUT)
verte = PWM(Pin(19), freq=1000)
bouton = Pin(18, Pin.IN, Pin.PULL_DOWN)
buzzer = Pin(23, Pin.OUT)
pir = Pin(27, Pin.IN)
pot = ADC(Pin(34)); pot.atten(ADC.ATTN_11DB)
ldr = ADC(Pin(35)); ldr.atten(ADC.ATTN_11DB)
servo = PWM(Pin(26), freq=50)
alarme = False
mouvement_alarme = False
while True:
    valeur = pot.read()
    lumiere = ldr.read()
    mouvement = pir.value()
    print("ADC =", valeur, "LDR =", lumiere, "PIR =", mouvement)
    if bouton.value() == 1:
        rouge.off()
        if valeur < 1000:
            servo.duty(26)
            verte.duty(1023)
            sleep(0.5)
            verte.duty(0)
            sleep(0.5)
        elif valeur < 2000:
            servo.duty(51)
            verte.duty(valeur // 4)
        elif valeur < 3000:
            servo.duty(77)
            verte.duty(valeur // 4)
        else:
            servo.duty(128)
            if valeur == 3000:
                verte.duty(valeur // 4)
            else:
                verte.duty(1023)
    else:
        servo.duty(26)
        verte.duty(0)
        if lumiere < 2000:
            rouge.on()
        else:
            rouge.off()
    if bouton.value() == 1 and valeur > 3000:
        if alarme == False:
            print("ALARME POTENTIOMETRE")
            for i in range(3):
                buzzer.on(); sleep(0.2)
                buzzer.off(); sleep(0.2)
            alarme = True
    else:
        alarme = False
    if mouvement == 1 and lumiere < 2000:
        if mouvement_alarme == False:
            print("MOUVEMENT DETECTE - NUIT")
            for i in range(3):
                buzzer.on(); sleep(0.2)
                buzzer.off(); sleep(0.2)
            mouvement_alarme = True
    else:
        mouvement_alarme = False
    sleep(0.1)
